  const dispatch = planner(catalog());
  assert.deepEqual(dispatch(book("first", 7)), {status:"booked", id:"first", remaining:1});
  assert.deepEqual(dispatch(book("too-many", 2)), {status:"full", id:"too-many", remaining:1});
  assert.equal(dispatch(book("too-many", 1)).status, "booked");
  assert.equal(dispatch(book("tomorrow", 8, {day:"2025-04-03"})).status, "booked");
  assert.equal(dispatch(book("iris-full", 3, {tenant:"iris"})).status, "full");
  assert.equal(dispatch(book("iris-ok", 2, {tenant:"iris"})).status, "booked");
  assert.equal(dispatch(book("unlisted-full", 6, {tenant:"fern"})).status, "full");
  assert.equal(dispatch(book("unlisted-ok", 5, {tenant:"fern"})).status, "booked");
  assert.equal(dispatch(book("archive-full", 6, {service:"archive"})).status, "full");
  assert.equal(dispatch(book("archive-ok", 5, {service:"archive"})).status, "booked");
});

test("imports, replay, conflicts and cancellations retain journal semantics", () => {
  const dispatch = planner(catalog());
  const original = book("first", 8);
  assert.equal(dispatch(original).status, "booked");
  assert.equal(dispatch(original).status, "replay");
  assert.equal(dispatch({...original, units:7}).status, "conflict");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch(original).status, "cancelled");
  assert.equal(dispatch({...original, units:7}).status, "conflict");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "replay");
  assert.equal(dispatch(book("imported", 10, {action:"import"})).status, "imported");
  assert.deepEqual(dispatch(book("blocked", 1)), {status:"full", id:"blocked", remaining:0});
  assert.equal(dispatch(book("imported", 10)).status, "replay");
  dispatch({service:"studio", action:"cancel", id:"imported"});
  assert.equal(dispatch(book("replacement", 8)).status, "booked");
  const summary = dispatch({service:"studio", action:"summary"});
  assert.deepEqual(summary.events.map(event => event.type),
    ["booked", "cancelled", "booked", "cancelled", "booked"]);
