  const dir = mkdtempSync(join(tmpdir(), "orchid-calendar-"));
  try {
    const path = join(dir, "diary.json");
    const feed = join(dir, "feed.json");
    const original = diary();
    writeFileSync(path, JSON.stringify(original));
    writeFileSync(feed, JSON.stringify(source()));
    const publish = () => execFileSync(process.execPath,
      [new URL("./utilization.mjs", import.meta.url).pathname, "publish-calendar", feed, path], {encoding:"utf8"});
    assert.deepEqual(JSON.parse(publish()), {edition:"orchid-quota", rows:2});
    const once = readFileSync(path, "utf8");
    const rows = JSON.parse(once);
    for (const row of original.filter(row => !(row.service === "studio" && row.tenant === "orchid" && row.day === "2025-04-02"))) {
      assert.deepEqual(rows.find(item => item.service === row.service && item.tenant === row.tenant && item.day === row.day), row);
